    values.add(2147483646);
    values.add(2147483647);
    Text seed = new Text("é\0😀|");
    if (mode == 2) { seed.append("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"); }
    Text retained = new Text("");
    long total = 0L;
    int round = 0;
    while (round < rounds) {
        int number = values.get(round % values.size());
        if (mode == 1) {
            retained.clear();
            retained.appendText(seed);
            retained.appendInt(number);
            total = total + (long)retained.byteLength() + (long)retained.byteAt(round % retained.byteLength());
        } else {
            Text value = seed.clone();
            value.appendInt(number);
            total = total + (long)value.byteLength() + (long)value.byteAt(round % value.byteLength());
        }
        round = round + 1;
    }
    println(total);
    return new Result<Unit,Text>.Ok(());
}
